import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`acupuncture-audit`,heroTitle:`Audit your acupuncture practice in minutes`,heroSubtitle:`Perplexity Computer reviews your practice website, local visibility, trust signals, and booking flow, then ranks the fixes most likely to drive appointments.`,inputUrlCta:`Audit my practice`,inputUrlPlaceholder:`yourpractice.com`,inputUrlPrefill:`Go to {url} and run a full acupuncture practice audit. 1) Review the website for service clarity, practitioner trust signals, condition pages, booking flow, and mobile conversion issues. 2) Audit local visibility, reviews, Google Business Profile signals, and patient education content. 3) Benchmark nearby acupuncture or holistic health practices where useful. 4) Recommend the highest-impact changes for appointment bookings and local discovery. 5) Deliver a prioritized action plan with rewritten copy, trust improvements, and next steps.`,heroOverlaySteps:[`Reviewing service pages, practitioner trust cues, and booking flow`,`Analyzing local visibility, reviews, and patient education content`,`Benchmarking nearby acupuncture and holistic health practices`,`Prioritized growth audit with copy and booking fixes ready to use`],generatingSteps:[`Visiting {url} to review your practice site and patient journey`,`Designing an agent to benchmark local competitors and visibility signals`,`Configuring recommendations for trust, education, and booking improvements`,`Packaging the work into a prioritized practice-growth action plan`],featureSectionTitle:`From local trust gaps to more booked appointments`,featureCardTitles:[`Connects to your practice workflow`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your practice audit into website review, local visibility, patient trust, and competitor benchmarking so the plan reflects how patients choose care.`,`Google Business Profile, Docs, Sheets, booking tools, and planning notes can stay connected so marketing fixes move into execution.`,`Service-page rewrites. Local SEO priorities. Review improvements. Booking-flow fixes. Computer gives you updates tied to more appointments.`],capabilitySectionTitle:`Your practice growth analyst, on demand`,capabilitySectionSubtitle:`Paste your acupuncture practice URL, step away, and come back to a clearer plan to drive appointments.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review treatment pages, practitioner bios, patient education, trust cues, and booking flow to find conversion gaps.`},{title:`Local Visibility Review`,description:`Computer can assess reviews, listings, Google Business Profile signals, and local search cues to show where competitors are winning.`},{title:`Patient Trust Analysis`,description:`Computer can identify missing proof, unclear claims, and confusing condition messaging that may keep patients from booking.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across Google Business Profile, docs, sheets, and booking workflows so your team can act quickly.`},{title:`Remember Your Services`,description:`Computer can remember your modalities, treatment focus, and ideal patient profile so future audits start from the right context.`},{title:`Refresh the Audit`,description:`Computer can revisit your presence later, compare changes, and suggest the next fix most likely to improve bookings.`}]});export{t as default};
